import { readFileSync } from "node:fs";
import { defineConfig } from "@hey-api/openapi-ts";

// Generates a typed client from the backend's committed OpenAPI contract
// (../shared/openapi.json, regenerated by `uv run --project backend python
// scripts/export_openapi.py`; CI checks drift on both files — TASK-FOUND-014).
const spec = JSON.parse(readFileSync("../shared/openapi.json", "utf-8"));

// The chat SSE response inlines TurnEvent's JSON Schema with local `#/$defs/...` refs, which
// are unresolvable from the OpenAPI document root (the ref parser crashes). The stream is not
// read through the generated client anyway: features/chat/stream.ts parses it and validates
// each event against shared/schemas/turn_event.schema.json (src/contracts/generated).
// ponytail: drop this once the backend exports the SSE schema under components/schemas.
const sse =
  spec.paths?.["/api/v1/chat/conversations/{conversation_id}/messages"]?.post?.responses?.[
    "200"
  ]?.content?.["text/event-stream"];
if (sse) sse.schema = { type: "string" };

export default defineConfig({
  input: { path: spec },
  output: "src/api/generated",
  plugins: ["@hey-api/typescript", "@hey-api/sdk", "@hey-api/client-fetch"],
});
